{
  "rules": [
    "If sentiment is positive (≥0.25) in recent history, model tends to under-forecast; adjust forecast upward by 1-3% of recent mean.",
    "If model shows gradual upward trend (e.g., +0.1–0.3 per day) but true outcome spikes, reduce forecast slope by 20–50% to avoid overshoot.",
    "When true outcome exceeds model by >5% for 3+ consecutive days, apply mean reversion: subtract 0.5–1.5% per day from forecast until convergence.",
    "If sentiment is neutral or negative (≤0.00) and model is rising, cap forecast at 10–15% below recent peak to avoid overconfidence.",
    "For 30-day horizon, if model is flat or slightly declining while true outcome is rising, add 0.5–1.0% per day to forecast to capture momentum.",
    "If sentiment history includes 0.20–0.25 and model is rising, expect 1–2 day lag; delay forecast peak by 1–2 days and reduce magnitude by 5–10%."
  ]
}
